//! Agent-facing views of Milkrice's data, shared by the `milkrice` CLI and the MCP server.
//!
//! Output is compact plain text (or JSON) and always labels where content came from:
//!   - NOTES       written by the user, verbatim
//!   - AI SUMMARY  generated by an LLM (named); may contain mistakes
//!   - TRANSCRIPT  produced by the local speech model (named); may contain mis-hearings
use crate::llm::speaker_name;
use crate::store::{Meeting, MeetingSummary, Store};
use crate::types::Segment;
use anyhow::{anyhow, bail, Result};
use chrono::{DateTime, Duration, Local, Utc};
use serde_json::{json, Value};
use std::collections::BTreeMap;
use std::fmt::Write;

pub fn short(id: &str) -> &str {
    &id[..id.len().min(8)]
}

fn local(d: DateTime<Utc>) -> String {
    d.with_timezone(&Local).format("%Y-%m-%d %H:%M").to_string()
}

fn mins(ms: u64) -> String {
    let m = (ms + 30_000) / 60_000;
    if m >= 60 { format!("{}h{:02}m", m / 60, m % 60) } else { format!("{m}m") }
}

fn ts(ms: u64) -> String {
    let s = ms / 1000;
    if s >= 3600 { format!("{}:{:02}:{:02}", s / 3600, (s % 3600) / 60, s % 60) } else { format!("{:02}:{:02}", s / 60, s % 60) }
}

/// "12:03" / "1:02:03" / "90" (seconds) -> ms
pub fn parse_ts(s: &str) -> Result<u64> {
    let parts: Vec<u64> = s.split(':').map(|p| p.trim().parse::<u64>()).collect::<std::result::Result<_, _>>()
        .map_err(|_| anyhow!("bad time '{s}', use mm:ss"))?;
    let secs = match parts.as_slice() {
        [s] => *s,
        [m, s] => m * 60 + s,
        [h, m, s] => h * 3600 + m * 60 + s,
        _ => bail!("bad time '{s}'"),
    };
    Ok(secs * 1000)
}

/// "7d", "24h", "2w" -> cutoff
pub fn parse_since(s: &str) -> Result<DateTime<Utc>> {
    let (n, unit) = s.split_at(s.len().saturating_sub(1));
    let n: i64 = n.parse().map_err(|_| anyhow!("bad --since '{s}', use e.g. 7d, 24h, 2w"))?;
    let d = match unit {
        "h" => Duration::hours(n),
        "d" => Duration::days(n),
        "w" => Duration::weeks(n),
        _ => bail!("bad --since unit in '{s}' (h, d, w)"),
    };
    Ok(Utc::now() - d)
}

pub fn resolve(store: &Store, id: &str) -> Result<Meeting> {
    let full = store.resolve_id(id)?.ok_or_else(|| anyhow!("no meeting with id '{id}' (see: milkrice ls)"))?;
    store.get_meeting(&full)?.ok_or_else(|| anyhow!("meeting vanished"))
}

fn people(m: &Meeting) -> String {
    m.attendees.iter().filter(|a| !a.is_self).map(|a| a.name.clone()).collect::<Vec<_>>().join(", ")
}

fn has(segments: usize, m: &MeetingSummary) -> String {
    let _ = m;
    format!("tx:{segments}")
}

// ------------------------------------------------------------------ list

pub fn list(store: &Store, query: Option<&str>, since: Option<DateTime<Utc>>, folder: Option<&str>, limit: usize, as_json: bool) -> Result<String> {
    let mut ms = store.list_meetings(query, 10_000)?;
    if let Some(s) = since {
        ms.retain(|m| m.created_at >= s);
    }
    let folders = store.list_folders()?;
    let fname = |id: &String| folders.iter().find(|f| &f.id == id).map(|f| f.name.clone()).unwrap_or_default();
    if let Some(want) = folder {
        let f = folders
            .iter()
            .find(|f| f.name.eq_ignore_ascii_case(want.trim()) || f.id.starts_with(want.trim()))
            .ok_or_else(|| anyhow!("no folder called '{want}' (see: milkrice folders)"))?;
        ms.retain(|m| m.folders.contains(&f.id));
    }
    ms.truncate(limit);
    if as_json {
        let v: Vec<Value> = ms
            .iter()
            .map(|m| {
                let full = store.get_meeting(&m.id).ok().flatten();
                json!({
                    "id": short(&m.id), "title": m.title, "at": local(m.created_at), "minutes": m.duration_ms / 60_000,
                    "people": m.attendees.iter().filter(|a| !a.is_self).map(|a| &a.name).collect::<Vec<_>>(),
                    "has_notes": full.as_ref().map(|f| !f.notes.trim().is_empty()).unwrap_or(false),
                    "has_ai_summary": full.as_ref().map(|f| !f.enhanced.trim().is_empty()).unwrap_or(false),
                    "transcript_lines": store.segments(&m.id).map(|s| s.len()).unwrap_or(0),
                    "folders": m.folders.iter().map(fname).collect::<Vec<_>>(),
                })
            })
            .collect();
        return Ok(serde_json::to_string(&v)?);
    }
    if ms.is_empty() {
        return Ok("no meetings".into());
    }
    let mut out = String::from("id       date             len   title · people [content]\n");
    for m in &ms {
        let full = store.get_meeting(&m.id)?.unwrap_or_default();
        let segs = store.segments(&m.id)?.len();
        let mut tags = Vec::new();
        if !full.notes.trim().is_empty() {
            tags.push("notes".to_string());
        }
        if !full.enhanced.trim().is_empty() {
            tags.push("ai".to_string());
        }
        if segs > 0 {
            tags.push(has(segs, m));
        }
        if m.status == "recording" {
            tags.push("LIVE".into());
        }
        for f in &m.folders {
            tags.push(format!("in:{}", fname(f).replace(' ', "_")));
        }
        let p = people(&full);
        let _ = writeln!(
            out,
            "{}  {}  {:>5} {}{} [{}]",
            short(&m.id),
            local(m.created_at),
            mins(m.duration_ms),
            if m.title.is_empty() { "Untitled" } else { &m.title },
            if p.is_empty() { String::new() } else { format!(" · {p}") },
            tags.join(" ")
        );
    }
    Ok(out.trim_end().to_string())
}

/// Folders with note counts.
pub fn folders(store: &Store, as_json: bool) -> Result<String> {
    let fs = store.list_folders()?;
    if as_json {
        return Ok(serde_json::to_string(&fs.iter().map(|f| json!({"name": f.name, "notes": f.count})).collect::<Vec<_>>())?);
    }
    if fs.is_empty() {
        return Ok("no folders".into());
    }
    Ok(fs.iter().map(|f| format!("{} ({})", f.name, f.count)).collect::<Vec<_>>().join("\n"))
}

// ------------------------------------------------------------------ show

#[derive(Clone, Copy, PartialEq)]
pub enum Section {
    Notes,
    Ai,
    Transcript,
}

pub fn parse_sections(s: &str) -> Result<Vec<Section>> {
    let mut v = Vec::new();
    for part in s.split(',') {
        match part.trim() {
            "notes" | "user" => v.push(Section::Notes),
            "ai" | "summary" => v.push(Section::Ai),
            "transcript" | "tx" => v.push(Section::Transcript),
            "all" => v.extend([Section::Ai, Section::Notes, Section::Transcript]),
            "" => {}
            x => bail!("unknown section '{x}' (notes, ai, transcript, all)"),
        }
    }
    Ok(v)
}

pub fn show(store: &Store, id: &str, sections: &[Section], as_json: bool) -> Result<String> {
    let m = resolve(store, id)?;
    let segs = store.segments(&m.id)?;
    if as_json {
        let mut v = json!({
            "id": short(&m.id), "title": m.title, "at": local(m.created_at), "minutes": m.duration_ms / 60_000,
            "attendees": m.attendees, "speakers": m.speakers, "status": m.status,
        });
        if sections.contains(&Section::Notes) {
            v["user_notes"] = json!({"source": "written by the user", "text": m.notes});
        }
        if sections.contains(&Section::Ai) {
            v["ai_summary"] = json!({"source": format!("generated by {}{}", if m.enhanced_by.is_empty() { "an LLM" } else { &m.enhanced_by }, if m.enhanced_edited { ", then edited by the user" } else { "" }), "edited_by_user": m.enhanced_edited, "markdown": m.enhanced});
        }
        if sections.contains(&Section::Transcript) {
            v["transcript"] = json!({
                "source": format!("speech model {}", if m.stt_model.is_empty() { "(local)" } else { &m.stt_model }),
                "lines": segs.iter().map(|s| json!({"t": ts(s.start_ms), "speaker": speaker_name(&s.speaker, &m.speakers), "text": s.text})).collect::<Vec<_>>(),
            });
        }
        return Ok(serde_json::to_string(&v)?);
    }
    let mut out = String::new();
    let p = people(&m);
    let _ = writeln!(
        out,
        "# {} ({})\n{} · {}{}",
        if m.title.is_empty() { "Untitled" } else { &m.title },
        short(&m.id),
        local(m.created_at),
        mins(m.duration_ms),
        if p.is_empty() { String::new() } else { format!(" · with {p}") }
    );
    for sec in sections {
        match sec {
            Section::Ai => {
                let by = if m.enhanced_by.is_empty() { "an LLM".to_string() } else { m.enhanced_by.clone() };
                let edited = if m.enhanced_edited { ", edited by the user" } else { "" };
                let _ = writeln!(out, "\n== AI SUMMARY (generated by {by}{edited}; may contain errors) ==");
                out.push_str(if m.enhanced.trim().is_empty() { "(none yet)" } else { m.enhanced.trim() });
                out.push('\n');
            }
            Section::Notes => {
                let _ = writeln!(out, "\n== NOTES (written by the user) ==");
                out.push_str(if m.notes.trim().is_empty() { "(none)" } else { m.notes.trim() });
                out.push('\n');
            }
            Section::Transcript => {
                let model = if m.stt_model.is_empty() { "local speech model".to_string() } else { m.stt_model.clone() };
                let _ = writeln!(out, "\n== TRANSCRIPT (speech-to-text by {model}; may contain mis-hearings) ==");
                out.push_str(&transcript_lines(&segs, &m.speakers, None, None, None, None, 400));
                out.push('\n');
            }
        }
    }
    if !sections.contains(&Section::Transcript) && !segs.is_empty() {
        let _ = writeln!(out, "\n({} transcript lines: milkrice tx {})", segs.len(), short(&m.id));
    }
    Ok(out.trim_end().to_string())
}

/// Merged-by-speaker transcript lines: "12:03 Priya: …".
pub fn transcript_lines(
    segs: &[Segment],
    names: &BTreeMap<String, String>,
    from: Option<u64>,
    to: Option<u64>,
    speaker: Option<&str>,
    grep: Option<&str>,
    max_lines: usize,
) -> String {
    let speaker = speaker.map(|s| s.to_lowercase());
    let grep = grep.map(|g| g.to_lowercase());
    let mut lines: Vec<(u64, String, String)> = Vec::new();
    let mut prev_idx: Option<usize> = None;
    for (idx, s) in segs.iter().enumerate() {
        if from.map(|f| s.end_ms < f).unwrap_or(false) || to.map(|t| s.start_ms > t).unwrap_or(false) {
            continue;
        }
        let mut name = speaker_name(&s.speaker, names);
        if s.speaker == "me" {
            name.push_str(" (user)");
        }
        if let Some(sp) = &speaker {
            if !name.to_lowercase().contains(sp) && s.speaker.to_lowercase() != *sp {
                continue;
            }
        }
        let adjacent = prev_idx.map(|p| p + 1 == idx).unwrap_or(false);
        prev_idx = Some(idx);
        match lines.last_mut() {
            Some((_, n, t)) if *n == name && grep.is_none() && adjacent => {
                t.push(' ');
                t.push_str(s.text.trim());
            }
            _ => lines.push((s.start_ms, name, s.text.trim().to_string())),
        }
    }
    if let Some(g) = &grep {
        lines.retain(|(_, _, t)| t.to_lowercase().contains(g));
    }
    if lines.is_empty() {
        return "(no matching lines)".into();
    }
    let total = lines.len();
    let mut out = String::new();
    for (start, name, text) in lines.iter().take(max_lines) {
        let _ = writeln!(out, "{} {}: {}", ts(*start), name, text);
    }
    if total > max_lines {
        let next = lines[max_lines].0;
        let _ = write!(out, "… {} more lines (use --from {})", total - max_lines, ts(next));
    }
    out.trim_end().to_string()
}

pub fn transcript(store: &Store, id: &str, from: Option<u64>, to: Option<u64>, speaker: Option<&str>, grep: Option<&str>, limit: usize, as_json: bool) -> Result<String> {
    let m = resolve(store, id)?;
    let segs = store.segments(&m.id)?;
    if as_json {
        let lines: Vec<Value> = segs
            .iter()
            .filter(|s| from.map(|f| s.end_ms >= f).unwrap_or(true) && to.map(|t| s.start_ms <= t).unwrap_or(true))
            .filter(|s| speaker.map(|sp| speaker_name(&s.speaker, &m.speakers).to_lowercase().contains(&sp.to_lowercase())).unwrap_or(true))
            .filter(|s| grep.map(|g| s.text.to_lowercase().contains(&g.to_lowercase())).unwrap_or(true))
            .take(limit)
            .map(|s| json!({"t": ts(s.start_ms), "speaker": speaker_name(&s.speaker, &m.speakers), "is_user": s.speaker == "me", "text": s.text}))
            .collect();
        return Ok(serde_json::to_string(&json!({"source": format!("speech model {}", m.stt_model), "lines": lines}))?);
    }
    let model = if m.stt_model.is_empty() { "local speech model".to_string() } else { m.stt_model.clone() };
    Ok(format!(
        "TRANSCRIPT {} \"{}\" (speech-to-text by {model})\n{}",
        short(&m.id),
        m.title,
        transcript_lines(&segs, &m.speakers, from, to, speaker, grep, limit)
    ))
}

// ------------------------------------------------------------------ search

#[derive(Clone, Copy, PartialEq)]
pub enum Scope {
    All,
    Notes,
    Ai,
    Transcript,
}

fn snippet(text: &str, q: &str, width: usize) -> Option<String> {
    let lower = text.to_lowercase();
    let i = lower.find(q)?;
    let mut a = i.saturating_sub(width / 2);
    while !text.is_char_boundary(a) {
        a -= 1;
    }
    let mut b = (i + q.len() + width / 2).min(text.len());
    while !text.is_char_boundary(b) {
        b += 1;
    }
    let s = text[a..b].replace('\n', " ");
    Some(format!("{}{}{}", if a > 0 { "…" } else { "" }, s.trim(), if b < text.len() { "…" } else { "" }))
}

pub fn search(store: &Store, query: &str, scope: Scope, limit: usize, as_json: bool) -> Result<String> {
    let q = query.to_lowercase();
    anyhow::ensure!(!q.trim().is_empty(), "empty query");
    let mut hits: Vec<(String, String, String, String, String)> = Vec::new(); // id, title, source, where, snippet
    for m in store.list_meetings(Some(query), 500)? {
        let full = store.get_meeting(&m.id)?.unwrap_or_default();
        if matches!(scope, Scope::All | Scope::Notes) {
            if let Some(sn) = snippet(&full.notes, &q, 120) {
                hits.push((m.id.clone(), m.title.clone(), "notes".into(), String::new(), sn));
            }
        }
        if matches!(scope, Scope::All | Scope::Ai) {
            if let Some(sn) = snippet(&full.enhanced, &q, 120) {
                hits.push((m.id.clone(), m.title.clone(), "ai".into(), String::new(), sn));
            }
        }
        if matches!(scope, Scope::All | Scope::Transcript) {
            for s in store.segments(&m.id)? {
                if let Some(sn) = snippet(&s.text, &q, 140) {
                    hits.push((m.id.clone(), m.title.clone(), "transcript".into(), format!("{} {}{}", ts(s.start_ms), speaker_name(&s.speaker, &full.speakers), if s.speaker == "me" { " (user)" } else { "" }), sn));
                }
            }
        }
        if hits.len() >= limit * 3 {
            break;
        }
    }
    hits.truncate(limit);
    if as_json {
        let v: Vec<Value> = hits.iter().map(|(id, t, src, w, sn)| json!({"id": short(id), "title": t, "source": src, "at": w, "snippet": sn})).collect();
        return Ok(serde_json::to_string(&v)?);
    }
    if hits.is_empty() {
        return Ok(format!("no matches for '{query}'"));
    }
    let mut out = String::new();
    for (id, title, src, w, sn) in hits {
        let _ = writeln!(out, "{} {} [{}{}] {}", short(&id), if title.is_empty() { "Untitled" } else { &title }, src, if w.is_empty() { String::new() } else { format!(" {w}") }, sn);
    }
    Ok(out.trim_end().to_string())
}

pub const OVERVIEW: &str = "Milkrice stores meetings locally. Each meeting has three kinds of content, always labelled:\n  NOTES       typed by the user during the meeting (ground truth of what they cared about)\n  AI SUMMARY  written afterwards by an LLM (may contain errors)\n  TRANSCRIPT  local speech-to-text, speaker-labelled; the user's own lines are marked '(user)', other speakers are named or 'Speaker N'\nIDs are 8-char prefixes from `ls`.";
